def _split_of(anchor: str) -> str:
    h = int(hashlib.sha256(anchor.encode()).hexdigest(), 16) % 10
    return "test" if h == 0 else "validation" if h == 1 else "train"


def _wchoice(rng, pairs):
    total = sum(w for _, w in pairs)
    x = rng.uniform(0, total)
    for v, w in pairs:
        x -= w
        if x <= 0:
            return v
    return pairs[-1][0]


def family_spec(rng: random.Random, split: str, fid: str, category: str) -> dict:
    weight, pool, desc = CATEGORIES[category]
    anchors = [a for a in ANCHORS[pool] if _split_of(a) == split] or ANCHORS[pool]
    length = _wchoice(rng, [((n, d), w) for n, d, w in LENGTHS])
    if category == "ending_critical":
        length = ("long", "81-185 words")
    if category == "self_correction_multiple" and length[0] == "short":
        length = ("medium", "26-80 words")
    profile = _wchoice(rng, CATEGORY_PROFILES.get(category, PROFILES))
    noop = category == "preservation_discourse" and rng.random() < 0.8 or \
        category not in ("self_correction_single", "self_correction_multiple", "vocabulary_authorized") \
        and rng.random() < NOOP_FAMILY_SHARE * 0.6
    req = []
    if category == "self_correction_single":
        req.append(f"exactly one explicit self-correction using the marker '{rng.choice(MARKERS)}'")
    elif category == "self_correction_multiple":
        n = rng.choice([2, 2, 3])
        ms = rng.sample(MARKERS, n)
        req.append(f"{n} separate explicit self-corrections using markers {ms}, each inside its own sentence")
    elif not noop and rng.random() < 0.18:
        req.append(f"one explicit self-correction using the marker '{rng.choice(MARKERS)}'")
    if category == "preservation_discourse":
        req.append("rely on " + ", ".join(rng.sample(
            ["'like' used as a speech habit", "'you know'", "'I think' hedging", "'I mean it' (emphasis, not a correction)",
             "emphasis 'actually' ('we actually shipped it')", "a sentence-initial 'No,' answer", "meaningful repetition "
             "('very, very important')", "'kind of' / 'sort of'", "a greeting and a sign-off"], 3)))
    if category == "ending_critical":
        req.append("the decisive fact (a number, name, date, or negation) appears only in the final sentence")
    if category == "spoken_list":
        req.append(rng.choice(["an explicit list introduction followed by 3-5 items",
                               "spoken steps ('step one ... step two ...') with 2-4 steps",
                               "an explicit list introduction followed by items and a closing sentence"]))
    if category == "asr_mishearing_preserve":
        req.append("one technical term was misrecognized as ordinary words (e.g. 'cube control' for kubectl); "
                   "no vocabulary is supplied, so the target keeps the misheard words exactly")
    if category == "vocabulary_authorized":
        req.append("the recognizer wrote a dictionary term's spoken alias; fill `vocabulary` with that "
                   "{canonical, spoken_alias} pair; spoken_input contains the alias, target the canonical form")
    if not noop and category not in ("vocabulary_authorized",):
        req.append(rng.choice(["light fillers (one or two um/uh)", "several fillers (um, uh, erm, hmm)",
                               "a repeated function word stutter like 'the the' plus a filler",
                               "no fillers, only punctuation and casing problems", "one filler"]))
    if noop:
        req.append("is_noop: spoken_input is already perfectly punctuated and capitalized prose (no newlines) "
                   "and target is identical to it")
    req.append(f"if people are mentioned, use names like {rng.sample(NAMES, 2)}; opening style: {rng.choice(OPENINGS)}")
    return {"family_id": fid, "category": category, "description": desc,
            "length": f"{length[0]} ({length[1]})", "destination_profile": profile,
            "topic_anchors": rng.sample(anchors, min(2, len(anchors))), "requirements": req,
            "is_noop": bool(noop), "split": split}


def seed_plan(split: str, n_families: int, start: int = 0, seed_tag: str = "") -> list[dict]:
    """Deterministic family specs; categories in proportion to their weights."""
    rng = random.Random(f"{CONFIG['experiment_id']}:{split}:{start}:{seed_tag}")
    cats = [c for c, (w, _, _) in CATEGORIES.items() for _ in range(w)]
    out = []
    for i in range(start, start + n_families):
        cat = cats[(i * 7 + rng.randrange(len(cats))) % len(cats)]
        out.append(family_spec(rng, split, f"f{split[:2]}{seed_tag}{i:05d}", cat))
    return out


