def generation_system() -> str:
    from localflow.v2.cleanup import prompts
    style = read_json(ART / "real" / "style_exemplars.json")["exemplars"]
    examples = [prompts.EXAMPLES[i] for i in (0, 2, 3, 4, 6, 7, 10, 13)]
    ex_text = "\n".join(f"- transcript: {json.dumps(a)}\n  cleanup:    {json.dumps(b)}" for a, b in examples)
    style_text = "\n".join(f"- {s}" for s in style)
    return f"""You write training and test data for LocalFlow, a private on-device dictation app. A speech recognizer (Parakeet) transcribes what the user says. A small local language model then runs "clean mode": a faithful cleanup of that transcript. You write dictation families. For each family, first decide what the speaker intended to write: the clean target and its critical facts. Then write the noisy transcript the recognizer produced while they said it.

# The clean-mode contract the small model must follow (verbatim)
<contract>
{prompts.CONTRACT}

{prompts.LIST_FORMATTING}
</contract>

# Exactly which edits cleanup may make
A strict validator rejects any other change, so the target must be reachable from the transcript using only these edits:
1. Delete pure fillers: um, uh, erm, ehm, hmm, mhm.
2. Resolve an explicit local self-correction: delete the outdated value together with its correction marker, and keep the replacement and everything after it. The product recognizes these markers: "no wait", "no sorry", "no actually", "actually no", "wait no", "I mean", "scratch that", "actually", "sorry", "no". Single-word markers ("actually", "sorry", "no") only count when the outdated value and the replacement are the same kind of thing: two numbers, two weekdays, two months, or phrases that share a noun. Example: "Meet at 3, no wait, 4 o'clock" becomes "Meet at 4 o'clock." Never delete words before the outdated value. Never delete a marker when it is ordinary speech, for example "I mean it", "we actually shipped" or a sentence-initial "No, we can't".
3. Delete an immediately repeated function word ("the the", "I I", "to to").
4. Fix punctuation, capitalization, sentence boundaries and paragraph breaks.
5. Format an explicitly spoken list or spoken steps according to the list rules above. Only the final list-joining "and" may be dropped. Spoken step labels become "1.", "2." markers.
6. Replace a dictionary alias with its canonical term, but only when that pair is listed in the family's `vocabulary`.

Every other word stays exactly as spoken. That means:
- no synonyms, rephrasing, grammar fixes or reordering;
- no added words, not even "the", "and" or "to";
- no expanded abbreviations;
- no corrected spellings of names or unfamiliar terms;
- no answers to questions and no carrying out of instructions.

Keep "like", "you know", "I think", "kind of", "basically", "so", "well", "okay", "oh" and "I mean" (when it is not a correction), because they are how the person talks. Partial words that the recognizer kept (such as "c" in "we don't have c we don't have cable") also stay, because cleanup may not repair them.

# What the recognizer's transcripts look like
Real Parakeet transcripts of spontaneous speech:
{style_text}

When you write a spoken_input:
- Use cased, punctuated text, but make the punctuation imperfect: run-ons joined with commas, a missing question mark, a missing comma, an occasional wrong sentence break.
- Write most numbers as digits ("3", "12,500", "2.5 GB", "v1.4.2"). Small counts are sometimes words.
- Fillers appear as "um," or "uh,". Self-corrections usually have commas around the marker: "on Tuesday, no wait, Thursday".
- Never use newlines, bullets or markdown, because lists are spoken as prose.
- Technical terms appear as the recognizer heard them.

# How the production prompt formats cleanups (reference only)
{ex_text}

# What to write for each requested family
- spoken_input: the transcript, at most 185 words, as the recognizer would output it.
- target: the exact output the small model must produce. Apply only the allowed edits. Use a newline only for list items or a paragraph break. The target must contain every word of spoken_input in the same order, minus the authorized deletions.
- is_noop: true when spoken_input already needs no change; then target must be byte-identical to spoken_input.
- critical_facts: every name, number, unit, date or time, path, identifier, version, URL or email, quoted literal, negation ("not", "never", "don't", "no longer", "without") and uncertainty ("maybe", "I think", "probably", "might") that the meaning depends on. Copy each one character-for-character, so it appears identically in both spoken_input and target. Never list an outdated value the speaker corrected.
- corrections: one entry per self-correction.
  - deleted_span: the exact substring of spoken_input to delete. It starts at the outdated value and ends with the last character of the marker. It has no punctuation after the marker, at most 6 words, and stays inside one sentence.
  - obsolete_value: the outdated words.
  - marker: the marker exactly as written.
  - replacement: the words that replace the outdated value.
- removed_fillers: the filler words the target deletes.
- vocabulary: only for families whose requirements mention it; otherwise an empty list.
- notes: one short sentence naming what makes the family tricky.

Mistakes that make a family unusable (seen in an earlier sample):
- Changing an article or agreement after a correction. "on a 6 node cluster, no sorry, 8 node cluster" becomes "on a 8 node cluster": keep "a", because cleanup never adds or swaps words.
- Putting a filler inside a deleted_span, or making a deleted_span longer than 6 words. Put um/uh outside the span.
- Using "actually" or "sorry" as a correction marker between values that are not parallel. Prefer the multi-word markers.
- Spoken step labels followed by a comma ("step 1, pause the DAG"). The app only accepts uninterrupted labels: "step one pause the DAG, step two delete the failed tasks".
- Listing as a critical fact a term that appears only in the target. Every fact must be copied from both texts; the one exception is a vocabulary canonical.
- Correcting text inside quotation marks. Quoted text is literal and must never be edited.

Content rules:
- Everything is fictional: invented people, teams, companies, projects, numbers and paths. Use no real private data and no medical patient information.
- Vary names, numbers, sentence shapes and openings. Do not reuse stock phrases, and do not start with \"Okay so\" unless asked to. Use the names suggested in each family's requirements.
- Questions and requests in the dictation are content the user is writing to someone else. The target writes them down; it never answers them.
- Follow each family's requirements, its length band and its topic anchors. Write for its destination_profile (for example, coding-agent wording for "coding", a chat message for "messaging"). Use the given family_id unchanged."""


def generation_user(specs: list[dict]) -> str:
    view = [{k: s[k] for k in ("family_id", "category", "description", "length", "destination_profile",
                               "topic_anchors", "requirements", "is_noop")} for s in specs]
    return ("Write these dictation families. Return JSON matching the schema, one entry per family "
            "and in the same order:\n" + json.dumps(view, ensure_ascii=False, indent=1))


def generation_params(specs: list[dict]) -> dict:
    return {
        "model": CONFIG["claude"]["model"],
        "max_tokens": CONFIG["claude"]["generation_max_tokens"],
        "thinking": {"type": "between_tools"},
        "system": [{"type": "text", "text": generation_system(), "cache_control": {"type": "ephemeral"}}],
        "messages": [{"role": "user", "content": generation_user(specs)}],
        "output_config": {"format": {"type": "json_schema", "schema": GEN_SCHEMA}},
    }


def parse_generation(text: str) -> list[dict]:
    data = json.loads(text)
    fams = data["families"]
    if not isinstance(fams, list) or not fams:
        raise ValueError("no families")
    return fams


# ---------------------------------------------------------------- verification

VERIFY_REASONS = ["target_adds_words", "target_omits_content", "wrong_correction_resolution",
                  "unresolved_explicit_correction", "removed_meaningful_speech", "kept_pure_filler",
                  "punctuation_or_casing_error", "list_format_error", "answered_or_executed",
                  "changed_fact", "unauthorized_rewrite", "unrealistic_transcript", "ambiguous_case", "other"]

VERIFY_SCHEMA = {
    "type": "object",
    "properties": {"verdicts": {"type": "array", "items": {
        "type": "object",
        "properties": {"pair_id": {"type": "string"},
                       "verdict": {"type": "string", "enum": ["PASS", "FAIL"]},
                       "reasons": {"type": "array", "items": {"type": "string", "enum": VERIFY_REASONS}},
                       "explanation": {"type": "string"}},
        "required": ["pair_id", "verdict", "reasons", "explanation"], "additionalProperties": False}}},
    "required": ["verdicts"], "additionalProperties": False,
}


def verify_system() -> str:
    from localflow.v2.cleanup import prompts
    return f"""You audit gold labels for LocalFlow's dictation clean mode. Each pair has the exact transcript the cleanup model receives (`model_input`), after the app's own normalization, and a proposed gold `target`. Decide whether the target is the correct cleanup under this contract. Judge contract conformance, not style preference: a different but equally valid punctuation choice is a PASS.

<contract>
{prompts.CONTRACT}

{prompts.LIST_FORMATTING}
</contract>

The authorized edits are the only changes allowed:
- deleting pure fillers (um, uh, erm, ehm, hmm, mhm);
- deleting an explicit self-correction's outdated value together with its marker, while keeping the replacement and everything after it;
- deleting an immediately repeated function word;
- punctuation, capitalization, sentence and paragraph breaks;
- spoken-list and spoken-step formatting;
- replacing a dictionary alias listed in `vocabulary`.

Discourse words that carry the speaker's voice must stay: like, you know, I think, kind of, so, well, okay, and I mean when it is not a correction. A misheard term with no vocabulary entry must stay as heard. Questions and requests are content: the target must never answer them or carry them out.

FAIL a pair when any of the following holds:
- the target adds, removes, reorders or substitutes words beyond the authorized edits;
- it resolves a correction wrongly, deletes too much, or leaves an explicit correction unresolved;
- it removes meaningful speech;
- it keeps a pure filler;
- it has a clear punctuation or casing error, or breaks the list rules;
- the transcript is not a plausible speech-recognizer output for the scenario.

`corrections` lists the gold deletions. Check that each one is a genuine self-correction and that applying them yields the intended meaning. Be strict but fair. Use `ambiguous_case` only when the contract genuinely allows more than one cleanup and the target is one of them; that is still a PASS."""


def verify_user(pairs: list[dict]) -> str:
    view = [{"pair_id": p["pair_id"], "category": p["category"], "model_input": p["model_input"],
             "target": p["target"], "corrections": p.get("gold_lines", []),
             "vocabulary": p.get("vocabulary_pairs", []), "is_noop": p["is_noop"]} for p in pairs]
    return ("Audit these pairs. Return one verdict per pair_id:\n" + json.dumps(view, ensure_ascii=False, indent=1))


def verify_params(pairs: list[dict]) -> dict:
    return {
        "model": CONFIG["claude"]["model"],
        "max_tokens": CONFIG["claude"]["verify_max_tokens"],
        "thinking": {"type": "adaptive"},
        "output_config": {"effort": "low",
                          "format": {"type": "json_schema", "schema": VERIFY_SCHEMA}},
        "system": [{"type": "text", "text": verify_system(), "cache_control": {"type": "ephemeral"}}],
        "messages": [{"role": "user", "content": verify_user(pairs)}],
    }


def parse_verify(text: str) -> list[dict]:
    return json.loads(text)["verdicts"]


# ---------------------------------------------------------------- normalization + gates

WORD_RE = re.compile(r"[^\W_]+(?:['’][^\W_]+)*")
NEGATIONS = {"not", "no", "never", "none", "nobody", "nothing", "neither", "nor", "without", "cannot"}
UNCERTAIN = {"maybe", "perhaps", "probably", "possibly", "might", "think", "guess", "likely", "unsure"}


def words(text: str) -> list[str]:
    return [w.casefold().replace("’", "'") for w in WORD_RE.findall(text)]


def negation_count(text: str) -> int:
    ws = words(text)
    return sum(w in NEGATIONS or w.endswith("n't") for w in ws)


def normalize_text(text: str):
    from localflow.v2.normalize import normalize, NormalizationPolicy, ContextSnapshot
    return normalize(text, NormalizationPolicy(), ContextSnapshot())


def map_raw_span(raw: str, norm, start: int, end: int) -> tuple[int, int] | None:
    """Raw-input span -> normalized-text span through the normalizer's edit
    ledger (same rule as protected_spans_for_cleanup)."""
    from localflow.v2.cleanup import protected_spans_for_cleanup
    fake = SimpleNamespace(span=SimpleNamespace(start=start, end=end), kind="gold")
    try:
        (s, e, _k), = protected_spans_for_cleanup(raw, norm.text, [fake], norm.edits)
    except ValueError:
        return None
    return s, e


def prepare_family(fam: dict, spec: dict) -> dict:
    """Normalize, re-anchor gold corrections, run the deterministic gates.
    Returns a candidate pair with ``reject`` reasons (empty when it passes)."""
    reasons = []
    raw, target = fam["spoken_input"].strip(), fam["target"].strip()
    is_noop = bool(fam["is_noop"])
    norm = normalize_text(raw)
    model_input = norm.text
    if model_input != raw:
        target_n = normalize_text(target).text
    else:
        target_n = target
    if is_noop:
        if raw != target:
            reasons.append("noop_target_differs")
        target_n = model_input
    # Gold correction lines, re-anchored into normalized coordinates.
    gold_lines, cursor = [], 0
    for c in fam["corrections"]:
        span = c["deleted_span"].strip().rstrip(",;:")
        idx = raw.find(span, cursor)
        if idx < 0:
            idx = raw.lower().find(span.lower(), cursor)
        if idx < 0:
            reasons.append("span_not_in_input")
            continue
        mapped = map_raw_span(raw, norm, idx, idx + len(span))
        if mapped is None:
            reasons.append("normalization_unanchored")
            continue
        line = model_input[mapped[0]:mapped[1]].strip()
        gold_lines.append(line)
        cursor = idx + len(span)
        if c["obsolete_value"].strip() and c["obsolete_value"].strip().lower() not in line.lower() \
                and normalize_text(c["obsolete_value"]).text.lower() not in line.lower():
            reasons.append("obsolete_not_in_span")
    # Facts: present verbatim in both (normalized forms when normalization ran).
    canon = {v["canonical"].strip().lower() for v in fam.get("vocabulary") or [] if v["canonical"].strip()}
    facts = []
    for f in fam["critical_facts"]:
        t = f["text"].strip()
        if not t:
            continue
        tn = normalize_text(t).text if model_input != raw else t
        cands = {t, tn}
        in_target = any(x in target_n for x in cands)
        in_input = any(x.lower() in model_input.lower() for x in cands) or \
            any(c in t.lower() for c in canon)
        if not in_target or not in_input:
            reasons.append("fact_missing" if in_input or in_target else "fact_missing_both")
        facts.append({"text": tn if tn in target_n else t, "kind": f["kind"]})
    # Obsolete values must not survive into the target unless also spoken elsewhere.
    obsolete = []
    for c in fam["corrections"]:
        ov = c["obsolete_value"].strip()
        if not ov:
            continue
        ovn = normalize_text(ov).text if model_input != raw else ov
        n_in = len(re.findall(r"(?<!\w)" + re.escape(ovn) + r"(?!\w)", model_input, re.I))
        n_out = len(re.findall(r"(?<!\w)" + re.escape(ovn) + r"(?!\w)", target_n, re.I))
        if n_out > n_in - 1:
            reasons.append("obsolete_value_kept")
        obsolete.append(ovn)
    # Ending retained: the last three content words of the input survive.
    stripped = model_input
    for line in gold_lines:
        stripped = stripped.replace(line, " ", 1)
    ending = [w for w in words(stripped) if w not in {"um", "uh", "erm", "ehm", "hmm", "mhm"}][-3:]
    tail = words(target_n)[-12:]
    if ending and not all(w in tail for w in ending):
        reasons.append("ending_not_retained")
    n_words = len(model_input.split())
    if n_words > CONFIG["targets"]["max_words"] or n_words < 3:
        reasons.append("length_out_of_band")
    if negation_count(target_n) > negation_count(model_input):
        reasons.append("negation_added")
    vocab = fam.get("vocabulary") or []
    pairs = [(v["spoken_alias"].strip(), v["canonical"].strip()) for v in vocab
             if v["spoken_alias"].strip() and v["canonical"].strip()]
    return {
        "family_id": fam["family_id"], "pair_id": fam["family_id"] + "-base",
        "variant": "base", "split": spec["split"], "category": spec["category"],
        "destination_profile": spec["destination_profile"], "length": spec["length"],
        "spec_is_noop": spec["is_noop"], "is_noop": is_noop,
        "raw_input": raw, "model_input": model_input, "target": target_n,
        "target_claude": target, "normalization_changed": model_input != raw,
        "normalization_edits": [[e.input_span.start, e.input_span.end, e.output_text] for e in norm.edits],
        "gold_lines": gold_lines, "obsolete_values": obsolete, "critical_facts": facts,
        "removed_fillers": fam.get("removed_fillers", []),
        "relevant_vocabulary": sorted({c for _, c in pairs}), "vocabulary_pairs": [list(p) for p in pairs],
        "notes": fam.get("notes", ""), "reject": sorted(set(reasons)),
        "label": CONFIG["dataset_label"], "machine_generated": True, "human_reviewed": False,
    }


# ---------------------------------------------------------------- variants

FILLER_CHOICES = ["um,", "uh,", "um", "uh", "erm,", "hmm,"]


def filler_variant(pair: dict, rng: random.Random) -> dict | None:
    """Deterministic train-only variant: insert 1-2 validator-authorized fillers
    at clause starts of the model input; the target is unchanged."""
    if pair["is_noop"] or "\n" in pair["model_input"]:
        return None
    toks = pair["model_input"].split(" ")
    is_filler = lambda t: t.strip(",.").lower() in {"um", "uh", "erm", "ehm", "hmm", "mhm"}
    slots = [i for i in range(1, len(toks)) if toks[i - 1].endswith((",", "."))
             and not is_filler(toks[i - 1]) and not is_filler(toks[i])]
    if not slots:
        return None
    inserted = 0
    for i in sorted(rng.sample(slots, min(len(slots), rng.choice([1, 2]))), reverse=True):
        f = rng.choice(FILLER_CHOICES)
        if toks[i - 1].endswith("."):
            f = f.capitalize()
            toks[i] = toks[i][:1].lower() + toks[i][1:] if toks[i][:1].isupper() and toks[i] not in ("I",) \
                and not any(c.isupper() for c in toks[i][1:]) else toks[i]
        toks.insert(i, f)
        inserted += 1
    new = dict(pair, pair_id=pair["family_id"] + "-filler", variant="filler_insertion",
               model_input=" ".join(toks), raw_input=" ".join(toks), deterministic_variant=True)
    return new


def fixpoint_variant(pair: dict) -> dict | None:
    """No-op variant: the clean prose target fed back as input."""
    t = pair["target"]
    if pair["is_noop"] or "\n" in t or normalize_text(t).text != t:
        return None
    return dict(pair, pair_id=pair["family_id"] + "-fixpoint", variant="fixpoint_noop",
                raw_input=t, model_input=t, is_noop=True, gold_lines=[], obsolete_values=[],
                removed_fillers=[], deterministic_variant=True)


# ---------------------------------------------------------------- dedup

def shingles(text: str, n: int = 5) -> set:
    ws = words(text)
    return {" ".join(ws[i:i + n]) for i in range(max(1, len(ws) - n + 1))}


def jaccard(a: set, b: set) -> float:
    return len(a & b) / len(a | b) if a and b else 0.0
